import csv
from pathlib import Path

SERVICES = (
    {"name": "Economy", "base": 2, "per_kg": 1, "days": 5, "zones": ["urban"]},
    {"name": "Express", "base": 5, "per_kg": 0.5, "days": 2, "zones": ["urban"]},
    {"name": "Swift", "base": 5, "per_kg": 0.5, "days": 2, "zones": ["urban"]},
)


def load(path="data/parcels.csv"):
    with Path(path).open(newline="") as stream:
        return list(csv.DictReader(stream))


def billable_kg(parcel):
    volume = float(parcel["length_cm"]) * float(parcel["width_cm"]) * float(parcel["height_cm"])
    return max(float(parcel["weight_kg"]), volume / 5000)


def scale_kg(parcel):
    return float(parcel["weight_kg"])


def quotes(parcel, weight=billable_kg):
    """Available quotes for a parcel. `weight` maps a parcel to the priced kilograms."""
    kg = weight(parcel)
    return [{"service": s["name"], "days": s["days"],
             "cost": round(s["base"] + s["per_kg"] * kg, 2)}
            for s in SERVICES if parcel["zone"] in s["zones"]]


def select_cheapest(parcels):
    """One entry per parcel, in input order, priced by scale weight only.

    Ties on cost go to the first service in SERVICES order.
    """
    selected = []
    for parcel in parcels:
        options = quotes(parcel, weight=scale_kg)
        if not options:
            selected.append({"id": parcel["id"], "status": "unavailable",
                             "reason": f"no service for zone '{parcel['zone']}'"})
            continue
        best = min(options, key=lambda q: q["cost"])
        selected.append({"id": parcel["id"], "status": "selected", "service": best["service"],
                         "days": best["days"], "cost": best["cost"]})
    return {"parcels": selected}


if __name__ == "__main__":
    import json
    import sys

    if len(sys.argv) > 1 and sys.argv[1] == "select":
        result = select_cheapest(load())
        if len(sys.argv) > 2:
            out = Path(sys.argv[2])
            out.parent.mkdir(parents=True, exist_ok=True)
            out.write_text(json.dumps(result, indent=2) + "\n")
        else:
            print(json.dumps(result, indent=2))
    else:
        print(json.dumps({p["id"]: quotes(p) for p in load()}, indent=2))
