cat >> tests/test_shipping.py <<'EOF'


def test_select_ignores_volume():
    from shipping import select_cheapest
    bulky = {"id": "B", "weight_kg": "2", "length_cm": "50", "width_cm": "40", "height_cm": "40", "zone": "urban"}
    compact = {"id": "C", "weight_kg": "2", "length_cm": "5", "width_cm": "5", "height_cm": "5", "zone": "urban"}
    a, b = select_cheapest([bulky, compact])["parcels"]
    assert {k: v for k, v in a.items() if k != "id"} == {k: v for k, v in b.items() if k != "id"}
    assert a["cost"] == 4.0 and a["service"] == "Economy"


def test_select_batch_keeps_order_and_unavailable():
    from shipping import select_cheapest
    result = select_cheapest(load())["parcels"]
    assert [p["id"] for p in result] == ["P1", "P2", "P3"]
    assert result[1] == {"id": "P2", "status": "selected", "service": "Economy", "days": 5, "cost": 3.0}
    assert result[2]["status"] == "unavailable" and result[2]["reason"]


def test_quotes_still_use_billable_weight():
    assert quotes(load()[0])[0]["cost"] == 18.0
